<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {useRouter} from 'vue-router'
import AppModal from '@/components/AppModal.vue'
import {demoMode,request} from '@/services/quality'
const router=useRouter();const token=ref(new URLSearchParams(window.location.hash.slice(1)).get('token')||'');const email=ref('');const name=ref('');const password=ref('');const confirmation=ref('');const open=ref(false);const busy=ref(false);const error=ref('');const logged=ref(!!sessionStorage.getItem('bestpharma.token'))
onMounted(()=>history.replaceState(null,'',window.location.pathname))
async function accept(){busy.value=true;error.value='';try{const d=await request<{token:string}>('/internal-invitations/accept','POST',{token:token.value,email:email.value,name:name.value,password:password.value||undefined,password_confirmation:confirmation.value||undefined});sessionStorage.removeItem('bestpharma.officine');sessionStorage.setItem('bestpharma.token',d.token);sessionStorage.setItem('bestpharma.platform','false');router.push('/dashboard/profil')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function signin(){router.push('/login?next='+encodeURIComponent('/internal-invitation#token='+token.value))}
</script>
<template><div class="registration-page"><header><RouterLink to="/login" class="brand">bestpharma.</RouterLink></header><section class="registration-content"><p class="eyebrow">INVITATION PERSONNELLE</p><h1>Rejoindre l’équipe d’accompagnement</h1><p class="page-subtitle">L’acceptation ouvre uniquement les fonctions internes proposées. Chaque accès à une officine nécessitera son approbation.</p><div class="module-links"><button v-if="!demoMode" class="button primary" @click="open=true">Consulter et accepter</button><button v-if="!logged" class="button secondary" @click="signin">J’ai déjà un compte</button></div><p v-if="demoMode" class="module-disclaimer">Invitation réelle disponible en mode API.</p></section><AppModal v-model="open" title="Accepter l’invitation interne" :busy="busy"><form id="internal-accept" class="form-body correction-form" @submit.prevent="accept"><p v-if="error" class="alert error" role="alert">{{error}}</p><label>Email destinataire<input v-model="email" type="email" required/></label><template v-if="!logged"><label>Nom<input v-model="name" required maxlength="120"/></label><label>Mot de passe<input v-model="password" type="password" required minlength="12" maxlength="128" autocomplete="new-password"/></label><label>Confirmation<input v-model="confirmation" type="password" required minlength="12" maxlength="128" autocomplete="new-password"/></label></template><p v-else>Le compte connecté doit correspondre à l’adresse invitée.</p></form><template #footer><button class="button secondary" :disabled="busy" @click="open=false">Annuler</button><button class="button primary" :disabled="busy" type="submit" form="internal-accept">Accepter</button></template></AppModal></div></template>
